private final CopyOnWriteArrayList<Listener> listeners = new CopyOnWriteArrayList<>();

void fire(Event e) {                        // no lock, no ConcurrentModificationException
    for (Listener l : listeners) l.onEvent(e);   // snapshot iterator
}

void register(Listener l) {
    listeners.add(l);                       // copies the whole backing array
}

