private final AtomicReference<Map<String, Integer>> routes =
    new AtomicReference<>(Map.of());

int lookup(String k) { return routes.get().get(k); }    // volatile read, no lock

void add(String k, int v) {
    routes.updateAndGet(cur -> {                        // CAS retry loop
        var next = new HashMap<>(cur);                  // copy-on-write
        next.put(k, v);
        return Map.copyOf(next);                        // immutable snapshot
    });
}
